-- create-table /RT/PACKAGES
CREATE TABLE "/RT/PACKAGES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "VERSION" VARCHAR(64) NOT NULL,
  "DESCRIPTION" TEXT,
  "INSTALLED_AT" TIMESTAMPTZ NOT NULL,
  "UPDATED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/PACKAGES#PK" PRIMARY KEY ("PACKAGE_ID")
);

-- create-table /RT/DOMAINS
CREATE TABLE "/RT/DOMAINS" (
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "DESCRIPTION" TEXT,
  "BASE_TYPE" VARCHAR(10) NOT NULL,
  "LENGTH" INTEGER,
  "DECIMALS" INTEGER,
  CONSTRAINT "/RT/DOMAINS#PK" PRIMARY KEY ("DOMAIN_NAME"),
  CONSTRAINT "/RT/DOMAINS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/DOMAINS#CK#BASE_TYPE" CHECK ("BASE_TYPE" IN ('CHAR', 'STRING', 'INT4', 'INT8', 'DEC', 'DATE', 'TIMESTAMP', 'BOOL', 'UUID', 'BLOB'))
);

-- create-table /RT/DOMAIN_VALUES
CREATE TABLE "/RT/DOMAIN_VALUES" (
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "VALUE" TEXT NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/DOMAIN_VALUES#PK" PRIMARY KEY ("DOMAIN_NAME", "POSITION"),
  CONSTRAINT "/RT/DOMAIN_VALUES#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/TABLES
CREATE TABLE "/RT/TABLES" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "DESCRIPTION" TEXT,
  "TENANT_SPECIFIC" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/TABLES#PK" PRIMARY KEY ("TABLE_NAME"),
  CONSTRAINT "/RT/TABLES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/EXTENSIONS
CREATE TABLE "/RT/EXTENSIONS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/EXTENSIONS#PK" PRIMARY KEY ("PACKAGE_ID", "TABLE_NAME"),
  CONSTRAINT "/RT/EXTENSIONS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/EXTENSIONS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/FIELDS
CREATE TABLE "/RT/FIELDS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FIELD_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "LOCAL_NAME" VARCHAR(63) NOT NULL,
  "DESCRIPTION" TEXT,
  "PACKAGE_ID" VARCHAR(16),
  "ORIGIN" VARCHAR(10) NOT NULL,
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "NOT_NULL" BOOLEAN NOT NULL,
  "DEFAULT_VALUE" TEXT,
  "KEY_POSITION" INTEGER,
  CONSTRAINT "/RT/FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FIELD_NAME"),
  CONSTRAINT "/RT/FIELDS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#CK#ORIGIN" CHECK ("ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT'))
);

-- create-table /RT/FOREIGN_KEYS
CREATE TABLE "/RT/FOREIGN_KEYS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FK_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "ORIGIN" VARCHAR(10) NOT NULL,
  "TARGET_TABLE" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/FOREIGN_KEYS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME"),
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TARGET" FOREIGN KEY ("TARGET_TABLE") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#ORIGIN" CHECK ("ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT'))
);

-- create-table /RT/FK_FIELDS
CREATE TABLE "/RT/FK_FIELDS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FK_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(63) NOT NULL,
  "TARGET_FIELD" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/FK_FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME", "POSITION"),
  CONSTRAINT "/RT/FK_FIELDS#FK#FOREIGN_KEY" FOREIGN KEY ("TABLE_NAME", "FK_NAME") REFERENCES "/RT/FOREIGN_KEYS" ("TABLE_NAME", "FK_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/LOG
CREATE TABLE "/RT/LOG" (
  "LOG_ID" UUID NOT NULL,
  "OPERATION" VARCHAR(16) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "VERSION_FROM" VARCHAR(64),
  "VERSION_TO" VARCHAR(64),
  "STARTED_AT" TIMESTAMPTZ NOT NULL,
  "FINISHED_AT" TIMESTAMPTZ,
  "STATUS" VARCHAR(10) NOT NULL,
  "MESSAGE" TEXT,
  CONSTRAINT "/RT/LOG#PK" PRIMARY KEY ("LOG_ID"),
  CONSTRAINT "/RT/LOG#CK#OPERATION" CHECK ("OPERATION" IN ('MIGRATE', 'INSTALL', 'UPGRADE', 'UNINSTALL', 'TENANT_DELETE')),
  CONSTRAINT "/RT/LOG#CK#STATUS" CHECK ("STATUS" IN ('SUCCESS', 'FAILED'))
);

-- create-table /RT/LOG_STATEMENTS
CREATE TABLE "/RT/LOG_STATEMENTS" (
  "LOG_ID" UUID NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "STATEMENT" TEXT NOT NULL,
  "DESTRUCTIVE" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/LOG_STATEMENTS#PK" PRIMARY KEY ("LOG_ID", "POSITION"),
  CONSTRAINT "/RT/LOG_STATEMENTS#FK#LOG" FOREIGN KEY ("LOG_ID") REFERENCES "/RT/LOG" ("LOG_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/MIGRATIONS
CREATE TABLE "/RT/MIGRATIONS" (
  "VERSION" INTEGER NOT NULL,
  "APPLIED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/MIGRATIONS#PK" PRIMARY KEY ("VERSION")
);

-- create-table /RT/PACKAGE_DEPS
CREATE TABLE "/RT/PACKAGE_DEPS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REQUIRED_ID" VARCHAR(16) NOT NULL,
  "VERSION_CONSTRAINT" TEXT,
  CONSTRAINT "/RT/PACKAGE_DEPS#PK" PRIMARY KEY ("PACKAGE_ID", "REQUIRED_ID"),
  CONSTRAINT "/RT/PACKAGE_DEPS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/PACKAGE_DEPS#FK#REQUIRED" FOREIGN KEY ("REQUIRED_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/TENANTS
CREATE TABLE "/RT/TENANTS" (
  "TENANT" VARCHAR(16) NOT NULL,
  "DESCRIPTION" TEXT,
  "CREATED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/TENANTS#PK" PRIMARY KEY ("TENANT")
);

